messages.content:
Your provider has no native tool calling. tool_choice=auto;parallel_tool_calls=false. You must output exactly one JSON object per turn and no Markdown.
To call a tool, output only an exact name from this turn's list. Shape example; replace values for the current task: {"tool_calls":[{"arguments":"1.1","name":"goal.update"}]}
For a final answer, output: {"final":"answer text"}
Select tools only from the following list. arguments must satisfy the corresponding JSON Schema:
[
  {
    "description": "Update the active Resident task only when interpretation, requirements or working state changes. Refine the origin request before complex work; revise requirements only with an exact quote from the current user message. Working items record a revisable plan, not user requirements. Keep the plan consistent with actual results and remaining content gaps before finishing. This tool cannot mark delivery or Goal completion; completed items do not prove either. Short direct answers need no update or plan. Use working in a separate call to save focus, next_move or plan items; refine/revise do not accept these fields.",
    "name": "goal.update",
    "parameters": {
      "anyOf": [
        {
          "additionalProperties": false,
          "properties": {
            "focus": {},
            "items": {},
            "next_move": {},
            "open_questions": {},
            "operation": {
              "enum": [
                "working"
              ]
            }
          },
          "required": [
            "operation",
            "focus",
            "next_move"
          ]
        },
        {
          "additionalProperties": false,
          "properties": {
            "interpretation": {},
            "operation": {
              "enum": [
                "refine"
              ]
            },
            "requirements": {}
          },
          "required": [
            "operation",
            "interpretation",
            "requirements"
          ]
        },
        {
          "additionalProperties": false,
          "properties": {
            "basis_quote": {},
            "basis_turn_id": {},
            "interpretation": {},
            "operation": {
              "enum": [
                "revise"
              ]
            },
            "requirements": {}
          },
          "required": [
            "operation",
            "basis_turn_id",
            "basis_quote",
            "interpretation",
            "requirements"
          ]
        }
      ],
      "properties": {
        "basis_quote": {
          "type": "string"
        },
        "basis_turn_id": {
          "type": "string"
        },
        "focus": {
          "type": "string"
        },
        "interpretation": {
          "type": "string"
        },
        "items": {
          "description": "For operation=working: replace the whole ordered work plan atomically. Omit to retain it; [] clears it. Use non-empty unique IDs and non-empty descriptions. Reorder, split, merge, remove abandoned steps or reopen completed items as observations require; this does not change requirements.",
          "items": {
            "properties": {
              "description": {
                "minLength": 1,
                "type": "string"
              },
              "id": {
                "minLength": 1,
                "type": "string"
              },
              "status": {
                "enum": [
                  "pending",
                  "in_progress",
                  "completed"
                ],
                "type": "string"
              }
            },
            "required": [
              "id",
              "description",
              "status"
            ],
            "type": "object"
          },
          "type": [
            "array",
            "null"
          ]
        },
        "next_move": {
          "type": "string"
        },
        "open_questions": {
          "items": {
            "type": "string"
          },
          "type": "array"
        },
        "operation": {
          "enum": [
            "working",
            "refine",
            "revise"
          ],
          "type": "string"
        },
        "requirements": {
          "items": {
            "properties": {
              "basis_turn_id": {
                "type": "string"
              },
              "description": {
                "type": "string"
              },
              "id": {
                "type": "string"
              },
              "verification": {
                "description": "content: explanation correctness and features inside the authored page, including page controls, dragging, playback, pause, seeking and saved scene restoration. presentation_delivery: actually save and deliver the requested page. reader_action: an explicitly requested host Reader operation such as navigating the book or changing its panels; requires an actual Reader effect. Page interactions and preview actions are content requirements, not reader_action. Keep the user's required behavior in description; choose verification by what must actually be delivered.",
                "enum": [
                  "content",
                  "presentation_delivery",
                  "reader_action"
                ],
                "type": "string"
              }
            },
            "required": [
              "id",
              "description",
              "basis_turn_id",
              "verification"
            ],
            "type": "object"
          },
          "type": "array"
        }
      },
      "required": [
        "operation"
      ],
      "type": "object"
    }
  },
  {
    "description": "Attach a note to a LID through a thin entry point whose persistence is delegated to memory. Returns note_id, which is the memory-layer ID.",
    "name": "reader.note",
    "parameters": {
      "properties": {
        "lid": {
          "type": "string"
        },
        "text": {
          "description": "Note content",
          "type": "string"
        }
      },
      "required": [
        "lid",
        "text"
      ],
      "type": "object"
    }
  },
  {
    "description": "Highlight source text at a LID. When the user specifies a sentence or quote, provide that exact quote; only its unique original occurrence is saved. Omit quote only when the user requests the whole passage. Persistence is delegated to memory; returns highlight_id.",
    "name": "reader.highlight",
    "parameters": {
      "properties": {
        "lid": {
          "type": "string"
        },
        "quote": {
          "description": "Exact requested original text within this LID; must match once",
          "type": "string"
        }
      },
      "required": [
        "lid"
      ],
      "type": "object"
    }
  },
  {
    "description": "Save highlight or position memory; qa records the user's original question after answering with book.query; context records sourced reader background, preferences, interests or sticking points. Use reader.note for every note: note is not a memory.save type. anchor_lid is the question or memory location. context may cite real LIDs supporting it.",
    "name": "memory.save",
    "parameters": {
      "properties": {
        "anchor_lid": {
          "type": "string"
        },
        "citations": {
          "description": "Optional real LIDs supporting this memory, primarily for context; invalid LIDs are dropped and the list may be empty",
          "items": {
            "type": "string"
          },
          "type": "array"
        },
        "content": {
          "type": "string"
        },
        "type": {
          "enum": [
            "highlight",
            "position",
            "qa",
            "context"
          ],
          "type": "string"
        }
      },
      "required": [
        "type",
        "anchor_lid",
        "content"
      ],
      "type": "object"
    }
  }
]
